158→// TransitionAndLog runs a session phase transition, applies actions via the
159→// handler, and logs the transition. Returns the first handler error from
160→// ApplyTransition (if any) so callers can surface it. The error is also
161→// logged internally for diagnostics.
162→// This is the single entry point for all state machine transitions to ensure
163→// consistent logging of phase changes.
164→func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
165→	oldPhase := state.Phase
166→	result := session.Transition(oldPhase, event, ctx)
167→	logCtx := logging.WithComponent(goCtx, "session")
168→
169→	handlerErr := session.ApplyTransition(goCtx, state, result, handler)
170→	if handlerErr != nil {
171→		logging.Error(logCtx, "action handler error during transition",
172→			slog.String("session_id", state.SessionID),
173→			slog.String("event", event.String()),
174→			slog.Any("error", handlerErr),
175→		)
176→	}
177→
178→	if result.NewPhase != oldPhase {
179→		logging.Info(logCtx, "phase transition",
180→			slog.String("session_id", state.SessionID),
181→			slog.String("event", event.String()),
182→			slog.String("from", string(oldPhase)),
183→			slog.String("to", string(result.NewPhase)),
184→		)
185→	} else {
186→		logging.Debug(logCtx, "phase unchanged",
187→			slog.String("session_id", state.SessionID),
188→			slog.String("event", event.String()),
189→			slog.String("phase", string(result.NewPhase)),
190→			slog.Any("result", result),
191→		)
192→	}
193→
194→	if handlerErr != nil {
195→		return fmt.Errorf("transition %s: %w", event, handlerErr)
196→	}
197→	return nil
198→}
