	})

	// 5. Agent stops
	env.SimulateStop(sess.ID, sess.TranscriptPath)

	// 6. Verify flag was cleared
	state, err = env.GetSessionState(sess.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
