470→func setupTranscript(sessionID string) string {
471→	home, err := os.UserHomeDir()
472→	if err != nil {
473→		fatal("home dir: %v", err)
474→	}
475→	transcriptDir := filepath.Join(home, ".vogon", "sessions")
476→	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
477→		fatal("mkdir transcript dir: %v", err)
478→	}
479→	path := filepath.Join(transcriptDir, sessionID+".jsonl")
480→	// Create empty file
481→	if err := os.WriteFile(path, nil, 0o644); err != nil {
482→		fatal("create transcript: %v", err)
483→	}
484→	return path
485→}
486→
487→type transcriptEntry struct {
488→	Type      string `json:"type"`
489→	Timestamp string `json:"timestamp"`
490→	Message   string `json:"message"`
491→}
492→
493→func appendTranscript(path, role, content string) {
494→	entry := transcriptEntry{
495→		Type:      role,
496→		Timestamp: time.Now().Format(time.RFC3339),
497→		Message:   content,
498→	}
499→	data, _ := json.Marshal(entry) //nolint:errchkjson // transcriptEntry has no unsafe types
500→	data = append(data, '\n')
501→
502→	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)
503→	if err != nil {
504→		return
505→	}
506→	defer f.Close()
507→	f.Write(data)
508→}
