117→func configureDroidRepoSettings(repoDir string) error {
118→	home, err := os.UserHomeDir()
119→	if err != nil {
120→		return fmt.Errorf("get home dir: %w", err)
121→	}
122→
123→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
124→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
125→
126→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
127→		return err
128→	}
129→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
130→		return fmt.Errorf("exclude droid settings from git: %w", err)
131→	}
132→	return nil
133→}
134→
135→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
136→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
137→	if err != nil {
138→		return err
139→	}
140→
141→	customModels, ok := globalSettings["customModels"]
142→	if !ok {
143→		return fmt.Errorf(
144→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
145→			globalSettingsPath,
146→			repoSettingsPath,
147→		)
148→	}
149→
150→	var models []json.RawMessage
151→	if err := json.Unmarshal(customModels, &models); err != nil {
152→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
153→	}
154→	if len(models) == 0 {
155→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
156→	}
157→
158→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
159→	if err != nil {
160→		return err
161→	}
162→	repoSettings["customModels"] = customModels
163→
164→	// Set the active custom model so interactive mode uses the BYOK model
165→	// instead of prompting for selection. The value must match the Model
166→	// field from the customModels entry (not the displayName).
167→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
168→	if err != nil {
169→		return fmt.Errorf("marshal model setting: %w", err)
170→	}
171→	repoSettings["model"] = json.RawMessage(modelJSON)
172→
173→	// High autonomy prevents Droid from asking for confirmation during
174→	// interactive E2E tests, which would cause hangs waiting for input.
175→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
176→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
177→
178→	out, err := json.MarshalIndent(repoSettings, "", "  ")
179→	if err != nil {
180→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
181→	}
182→	out = append(out, '\n')
183→
184→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
185→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
186→	}
187→	return nil
188→}
189→
190→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
191→	data, err := os.ReadFile(path)
192→	if err != nil {
193→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
194→	}
195→
196→	var parsed map[string]json.RawMessage
197→	if err := json.Unmarshal(data, &parsed); err != nil {
198→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
199→	}
200→	if parsed == nil {
201→		parsed = make(map[string]json.RawMessage)
202→	}
203→	return parsed, nil
204→}
205→
206→func ensureGitInfoExcludeContains(repoDir, entry string) error {
207→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
208→
209→	data, err := os.ReadFile(excludePath)
210→	if err != nil && !errors.Is(err, os.ErrNotExist) {
211→		return fmt.Errorf("read %s: %w", excludePath, err)
212→	}
213→
214→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
215→	for _, line := range strings.Split(normalized, "\n") {
216→		if strings.TrimSpace(line) == entry {
217→			return nil
218→		}
219→	}
220→
221→	var b strings.Builder
222→	if len(data) > 0 {
223→		b.Write(data)
224→		if data[len(data)-1] != '\n' {
225→			b.WriteByte('\n')
226→		}
227→	}
228→	b.WriteString(entry)
229→	b.WriteByte('\n')
230→
231→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
232→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
233→	}
234→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
235→		return fmt.Errorf("write %s: %w", excludePath, err)
236→	}
237→	return nil
238→}
