240→// ForEachAgent runs fn as a parallel subtest for every registered agent.
241→// It handles repo setup, concurrency gating, context timeout, and cleanup.
242→// The timeout is scaled by each agent's TimeoutMultiplier.
243→//
244→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
245→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
246→// panic and restarts the entire scenario with a fresh repository, up to
247→// maxScenarioRestarts times. This avoids stale CLI session state from the
248→// failed attempt poisoning the retry.
249→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
250→	t.Helper()
251→	t.Parallel()
252→	all := agents.All()
253→	if len(all) == 0 {
254→		t.Skip("no agents registered (check E2E_AGENT filter)")
255→	}
256→	for _, agent := range all {
257→		t.Run(agent.Name(), func(t *testing.T) {
258→			// Use the global test deadline for slot wait so we don't
259→			// skip prematurely — only bail if the whole binary is dying.
260→			slotCtx := context.Background()
261→			if deadline, ok := t.Deadline(); ok {
262→				var cancel context.CancelFunc
263→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
264→				defer cancel()
265→			}
266→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
267→				t.Fatalf("timed out waiting for agent slot: %v", err)
268→			}
269→			defer agents.ReleaseSlot(agent)
270→
271→			// Per-test timeout starts after slot is acquired, scaled
272→			// by the agent's multiplier (e.g. 2.5× for gemini).
273→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
274→
275→			var prevState *RepoState
276→			for attempt := range maxScenarioRestarts + 1 {
277→				s := SetupRepo(t, agent)
278→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
279→
280→				// On restart, suppress artifact capture from the previous
281→				// failed attempt so it doesn't overwrite the final one.
282→				if prevState != nil {
283→					prevState.skipArtifacts = true
284→				}
285→
286→				restarted := runScenario(t, s, ctx, fn)
287→				cancel()
288→
289→				if !restarted {
290→					return
291→				}
292→				prevState = s
293→				if attempt >= maxScenarioRestarts {
294→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
295→				}
296→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
297→			}
298→		})
299→	}
300→}
