package main

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestParsePrompt_Push(t *testing.T) {
	t.Parallel()

	t.Run("commit and push", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("create a file at hello.txt about greetings, then commit and push")
		kinds := actionKinds(actions)
		assert.Equal(t, []string{"create", "commit", "push"}, kinds)
	})

	t.Run("push alone", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("push")
		kinds := actionKinds(actions)
		assert.Equal(t, []string{"push"}, kinds)
	})

	t.Run("git push", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("create a file at foo.txt about foo, commit, then git push")
		kinds := actionKinds(actions)
		assert.Equal(t, []string{"create", "commit", "push"}, kinds)
	})

	t.Run("do not push", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("create a file at foo.txt about foo, commit. Do not push.")
		kinds := actionKinds(actions)
		assert.Equal(t, []string{"create", "commit"}, kinds)
		for _, a := range actions {
			assert.NotEqual(t, "push", a.kind)
		}
	})

	t.Run("don't push", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("create a file at bar.txt about bars and commit. Don't push it.")
		kinds := actionKinds(actions)
		require.NotContains(t, kinds, "push")
	})

	t.Run("numbered steps with push", func(t *testing.T) {
		t.Parallel()
		actions := parsePrompt("(1) create a file at step.txt about steps (2) commit (3) push")
		kinds := actionKinds(actions)
		assert.Equal(t, []string{"create", "commit", "push"}, kinds)
	})
}

func actionKinds(actions []action) []string {
	kinds := make([]string, len(actions))
	for i, a := range actions {
		kinds[i] = a.kind
	}
	return kinds
}

